const raw = $input.first().json || {};
const text = raw.output || raw.response || raw.text || raw.message || '';

const tags = ['RESUMEN_EJECUTIVO', 'COMO_VAMOS', 'PROYECTADO', 'DETALLES', 'METRICAS_JSON'];

// Acepta delimitadores con o sin asteriscos: [TAG] o **[TAG]** o *[TAG]*
function findOpeningPos(t) {
  const re = new RegExp('\\*{0,2}\\s*\\[' + t + '\\]\\s*\\*{0,2}', 'i');
  const m = text.match(re);
  if (!m) return null;
  return { start: m.index, len: m[0].length };
}
function findClosingPos(t) {
  const re = new RegExp('\\*{0,2}\\s*\\[\\/' + t + '\\]\\s*\\*{0,2}', 'i');
  const m = text.match(re);
  return m ? m.index : null;
}

// Localizar todas las aperturas presentes y ordenar por posición
const openings = tags.map(t => {
  const op = findOpeningPos(t);
  return op ? { tag: t, start: op.start, contentStart: op.start + op.len } : null;
}).filter(Boolean).sort((a, b) => a.start - b.start);

const sections = {};
openings.forEach((p, i) => {
  const closing = findClosingPos(p.tag);
  const nextStart = i + 1 < openings.length ? openings[i + 1].start : text.length;
  // Usar cierre solo si está dentro del rango del bloque actual; si no, usar próximo opening
  const end = (closing !== null && closing > p.contentStart && closing <= nextStart) ? closing : nextStart;
  sections[p.tag] = text.substring(p.contentStart, end).trim();
});

const resumen     = sections['RESUMEN_EJECUTIVO'] || '';
const comoVamos   = sections['COMO_VAMOS'] || '';
const proyectado  = sections['PROYECTADO'] || '';
const detalles    = sections['DETALLES'] || '';
const metricasStr = sections['METRICAS_JSON'] || '';

let metricas = null;
let otSnapshot = null;
if (metricasStr) {
  try {
    const clean = metricasStr.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
    const parsed = JSON.parse(clean);
    metricas = parsed;
    otSnapshot = parsed.ot_futuras || [];
  } catch (e) {
    metricas = { parse_error: String(e), raw: metricasStr.substring(0, 500) };
    otSnapshot = [];
  }
}

const fallback = !resumen && !comoVamos && !proyectado;
const esc = (s) => String(s || '').replace(/'/g, "''");

return [{ json: {
  resumen:     resumen    || (fallback ? text : 'Sin resumen ejecutivo.'),
  como_vamos:  comoVamos  || '',
  proyectado:  proyectado || '',
  detalles:    detalles   || '',
  metricas:    metricas,
  ot_snapshot: otSnapshot || [],
  fecha_hoy:   new Date().toISOString().slice(0, 10),
  fallback,
  _sql_resumen:     esc(resumen || (fallback ? text : 'Sin resumen ejecutivo.')),
  _sql_como_vamos:  esc(comoVamos),
  _sql_proyectado:  esc(proyectado),
  _sql_detalles:    esc(detalles),
  _sql_metricas:    esc(JSON.stringify(metricas || {})),
  _sql_ot_snapshot: esc(JSON.stringify(otSnapshot || []))
} }];
